#[cfg(test)]
mod tests {
    use std::collections::BTreeMap;

    use super::write_guard_logic::{
        Disk, Extent, LOG_HEADER_SIZE, LOG_REGION_OFFSET, SCRATCH_SECTOR, WriteMarker, crc32,
        judge, log_region_bytes, neofs_volume_bytes, provisioning_log_header, scratch_sector,
        scratch_valid, seal,
    };

    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * MIB;
    const SINK: u64 = 16 * MIB;

    /// A sparse disk image: unwritten bytes read as zero.
    struct Image {
        capacity: u64,
        sector: u64,
        bytes: BTreeMap<u64, u8>,
        /// A byte range whose reads fail (a bad sector).
        bad: Option<(u64, u64)>,
    }

    impl Image {
        fn new(capacity: u64, sector: u64) -> Self {
            Self {
                capacity,
                sector,
                bytes: BTreeMap::new(),
                bad: None,
            }
        }

        fn put(&mut self, offset: u64, data: &[u8]) {
            for (i, &b) in data.iter().enumerate() {
                self.bytes.insert(offset + i as u64, b);
            }
        }
    }

    impl Disk for Image {
        fn capacity(&self) -> u64 {
            self.capacity
        }

        fn sector_size(&self) -> u64 {
            self.sector
        }

        fn read(&self, offset: u64, out: &mut [u8]) -> bool {
            let end = offset + out.len() as u64;
            if end > self.capacity {
                return false;
            }
            if let Some((a, b)) = self.bad
                && offset < b
                && a < end
            {
                return false;
            }
            out.fill(0);
            for (&at, &b) in self.bytes.range(offset..end) {
                out[(at - offset) as usize] = b;
            }
            true
        }
    }

    /// A NEOFSv1 superblock, laid out by hand from the format (magic, version
    /// 1, log2 block size 12, type version 1, total_blocks at 16, BLAKE3 of
    /// bytes 0..480 at 480).
    fn neofs_superblock(total_blocks: u64) -> [u8; 512] {
        let mut sb = [0u8; 512];
        sb[..8].copy_from_slice(b"NEOFSv1\0");
        sb[8..10].copy_from_slice(&1u16.to_le_bytes());
        sb[10..12].copy_from_slice(&12u16.to_le_bytes());
        sb[12] = 1;
        sb[16..24].copy_from_slice(&total_blocks.to_le_bytes());
        let h = seal(&sb[..480]);
        sb[480..].copy_from_slice(&h);
        sb
    }

    /// A GPT laid out by hand (UEFI 2.10 §5.3): 128 x 128-byte entries, the
    /// primary header at LBA 1 with its entries at `entries_lba`, the backup
    /// entries just past the last usable LBA and the backup header in the
    /// device's last LBA, both CRCs filled in. `parts` are (first, last) LBAs.
    fn put_gpt(
        img: &mut Image,
        first_usable: u64,
        last_usable: u64,
        entries_lba: u64,
        count: u32,
        parts: &[(u64, u64)],
    ) {
        let ss = img.sector;
        let last_lba = img.capacity / ss - 1;
        let mut entries = vec![0u8; count as usize * 128];
        for (i, (first, last)) in parts.iter().enumerate() {
            let e = &mut entries[i * 128..(i + 1) * 128];
            e[0] = 0xa0 + i as u8; // any non-zero type GUID
            e[32..40].copy_from_slice(&first.to_le_bytes());
            e[40..48].copy_from_slice(&last.to_le_bytes());
        }
        let header = |my: u64, alt: u64, at: u64| {
            let mut h = [0u8; 92];
            h[..8].copy_from_slice(b"EFI PART");
            h[8..12].copy_from_slice(&0x0001_0000u32.to_le_bytes());
            h[12..16].copy_from_slice(&92u32.to_le_bytes());
            h[24..32].copy_from_slice(&my.to_le_bytes());
            h[32..40].copy_from_slice(&alt.to_le_bytes());
            h[40..48].copy_from_slice(&first_usable.to_le_bytes());
            h[48..56].copy_from_slice(&last_usable.to_le_bytes());
            h[72..80].copy_from_slice(&at.to_le_bytes());
            h[80..84].copy_from_slice(&count.to_le_bytes());
            h[84..88].copy_from_slice(&128u32.to_le_bytes());
            h[88..92].copy_from_slice(&crc32(&entries).to_le_bytes());
            let c = crc32(&h);
            h[16..20].copy_from_slice(&c.to_le_bytes());
            h
        };
        img.put(ss, &header(1, last_lba, entries_lba));
        img.put(entries_lba * ss, &entries);
        img.put(last_lba * ss, &header(last_lba, 1, last_usable + 1));
        img.put((last_usable + 1) * ss, &entries);
    }

    /// A GPT disk shaped like a Windows install: protective MBR, primary
    /// header at LBA 1 with 128 x 128-byte entries at LBA 2, ESP / MSR / C: /
    /// recovery partitions, backup header in the last LBA.
    fn windows_gpt(capacity: u64) -> Image {
        let ss = 512u64;
        let last_lba = capacity / ss - 1;
        let mut img = Image::new(capacity, ss);
        // Protective MBR: one 0xEE entry covering the disk.
        let mut mbr = [0u8; 512];
        mbr[446 + 4] = 0xee;
        mbr[446 + 8..446 + 12].copy_from_slice(&1u32.to_le_bytes());
        mbr[446 + 12..446 + 16].copy_from_slice(&u32::MAX.to_le_bytes());
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        img.put(0, &mbr);
        let last_usable = last_lba - 33;
        // ESP 100 MiB from 1 MiB, MSR 16 MiB, C: to 1 GiB short of the end,
        // recovery after it.
        let parts = [
            (2048u64, 2048 + 204_800 - 1),
            (206_848, 206_848 + 32_768 - 1),
            (239_616, last_usable - 2_097_152),
            (last_usable - 2_097_151, last_usable),
        ];
        put_gpt(&mut img, 34, last_usable, 2, 128, &parts);
        img
    }

    /// The Windows disk with sealed, valid markers at every probe offset.
    /// The scratch sector is the device's last sector, where the backup GPT
    /// header lives, so `scratch` also destroys the backup.
    fn windows_with_markers(cap: u64, scratch: bool) -> Image {
        let mut img = windows_gpt(cap);
        img.put(MIB, &neofs_superblock(1000));
        img.put(64 * MIB, &neofs_superblock(1000));
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        if scratch {
            img.put(cap - SCRATCH_SECTOR as u64, &scratch_sector(cap));
        }
        img
    }

    /// Zero `len` bytes at `at`.
    fn wipe(img: &mut Image, at: u64, len: usize) {
        img.put(at, &vec![0u8; len]);
    }

    /// CRC32 against independent known answers: the standard check value,
    /// and a real primary GPT header (92 bytes, from the ISO xorriso builds
    /// for this kernel, read raw), whose stored CRC is at bytes 16..20.
    #[test]
    fn crc32_known_answers() {
        assert_eq!(crc32(b"123456789"), 0xcbf4_3926);
        assert_eq!(crc32(b""), 0);
        let hex = "4546492050415254000001005c0000006c96324a000000000100000000000000\
                   cf9f0300000000004000000000000000a29f030000000000e2a5ccda8f562249\
                   b808fc00f969284c1400000000000000b000000080000000281a39a2";
        let hex: String = hex.split_whitespace().collect();
        let mut h: Vec<u8> = (0..hex.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
            .collect();
        assert_eq!(h.len(), 92);
        let stored = u32::from_le_bytes(h[16..20].try_into().unwrap());
        assert_eq!(stored, 0x4a32_966c);
        h[16..20].fill(0);
        assert_eq!(crc32(&h), stored);
    }

    /// Our own boot ISO's GPT (xorriso: first usable 64, 176 entries at LBA
    /// 20, backup at the end of the image), written to a larger disk with a
    /// sink provisioned past the image: the sink still arms, the OptiPlex
    /// layout.
    #[test]
    fn sink_beyond_our_iso_gpt_arms() {
        let cap = 4 * GIB;
        let mut img = Image::new(cap, 512);
        let mut mbr = [0u8; 512];
        mbr[446 + 4] = 0xee;
        mbr[446 + 8..446 + 12].copy_from_slice(&1u32.to_le_bytes());
        mbr[446 + 12..446 + 16].copy_from_slice(&237_519u32.to_le_bytes());
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        img.put(0, &mbr);
        // The image's backup sits at LBA 237519, not at the device's end.
        let parts = [(64, 147), (148, 5907), (5908, 236_871), (236_872, 237_471)];
        let mut entries = vec![0u8; 176 * 128];
        for (i, (first, last)) in parts.iter().enumerate() {
            let e = &mut entries[i * 128..(i + 1) * 128];
            e[0] = 0xa0 + i as u8;
            e[32..40].copy_from_slice(&(*first as u64).to_le_bytes());
            e[40..48].copy_from_slice(&(*last as u64).to_le_bytes());
        }
        let mut h = [0u8; 92];
        h[..8].copy_from_slice(b"EFI PART");
        h[8..12].copy_from_slice(&0x0001_0000u32.to_le_bytes());
        h[12..16].copy_from_slice(&92u32.to_le_bytes());
        h[24..32].copy_from_slice(&1u64.to_le_bytes());
        h[32..40].copy_from_slice(&237_519u64.to_le_bytes());
        h[40..48].copy_from_slice(&64u64.to_le_bytes());
        h[48..56].copy_from_slice(&237_474u64.to_le_bytes());
        h[72..80].copy_from_slice(&20u64.to_le_bytes());
        h[80..84].copy_from_slice(&176u32.to_le_bytes());
        h[84..88].copy_from_slice(&128u32.to_le_bytes());
        h[88..92].copy_from_slice(&crc32(&entries).to_le_bytes());
        let c = crc32(&h);
        h[16..20].copy_from_slice(&c.to_le_bytes());
        img.put(512, &h);
        img.put(20 * 512, &entries);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert_eq!(arming.table, "gpt", "{arming:?}");
        assert_eq!(arming.claims.len(), 1, "{arming:?}");
        assert!(arming.allows(LOG_REGION_OFFSET, LOG_REGION_OFFSET + 4096));
        assert!(!arming.allows(0, 512));
        assert!(
            !arming.allows(237_519 * 512, 237_520 * 512),
            "the image's backup header"
        );
    }

    /// Janus F1 (a): only the primary's entry-array LBA changed, to a
    /// zeroed area, CRCs left stale. It used to read as an empty GPT and arm
    /// the sink. Now the primary is invalid and the backup is honoured.
    #[test]
    fn f1_a_moved_entry_array_with_stale_crcs() {
        let cap = 954 * GIB;
        let mut img = windows_with_markers(cap, false);
        img.put(512 + 72, &(GIB / 512).to_le_bytes());
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt-backup");
        // And with the backup gone too: the whole disk is protected.
        wipe(&mut img, cap - 512, 512);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
    }

    /// The backup header replaced by a sealed scratch sector, so each case
    /// below tests the primary alone, with every marker present.
    fn windows_primary_only(cap: u64) -> Image {
        windows_with_markers(cap, true)
    }

    /// F1 (b): a primary header whose CRC does not match.
    #[test]
    fn f1_b_bad_header_crc() {
        let cap = 954 * GIB;
        let mut img = windows_primary_only(cap);
        let mut b = [0u8; 1];
        img.read(512 + 16, &mut b);
        img.put(512 + 16, &[b[0] ^ 1]);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
    }

    /// F1 (c): the entry for C: deleted, entry-array CRC left stale (the
    /// partition over the sink would otherwise vanish).
    #[test]
    fn f1_c_bad_entry_array_crc() {
        let cap = 954 * GIB;
        let mut img = windows_primary_only(cap);
        wipe(&mut img, 2 * 512 + 2 * 128, 128);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
    }

    /// F1 (d): the primary corrupt, the backup valid with the Windows
    /// partitions: the backup's partitions block every claim.
    #[test]
    fn f1_d_primary_corrupt_backup_valid() {
        let cap = 954 * GIB;
        let mut img = windows_with_markers(cap, false);
        wipe(&mut img, 512, 512);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt-backup");
        assert_eq!(arming.blocked_by_table, 2, "neofs and sink blocked");
        // The backup says C: covers the sink; deleting that entry from the
        // backup without fixing its CRC leaves no valid copy.
        wipe(&mut img, (cap / 512 - 33) * 512 + 2 * 128, 128);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
    }

    /// F1 (e): both copies corrupt (header CRCs off by one bit).
    #[test]
    fn f1_e_both_copies_corrupt() {
        let cap = 954 * GIB;
        let mut img = windows_with_markers(cap, false);
        for at in [512, cap - 512] {
            let mut b = [0u8; 1];
            img.read(at + 16, &mut b);
            img.put(at + 16, &[b[0] ^ 0x80]);
        }
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
    }

    /// Structural bounds, each with valid CRCs (a re-sealed header must
    /// still make sense): an entry array over the usable range, a header
    /// naming the wrong LBA, a partition outside the usable range, a
    /// count that overflows the array limit.
    #[test]
    fn f1_structurally_invalid_gpts_are_opaque() {
        let cap = 8 * GIB;
        let last = cap / 512 - 1;
        let lu = last - 33;
        // (what, entry-array LBA, partitions), all with first usable 34.
        type Case<'a> = (&'a str, u64, &'a [(u64, u64)]);
        let cases: [Case; 3] = [
            ("entries over the usable range", 40, &[]),
            ("partition past last usable", 2, &[(2048, lu + 1)]),
            ("partition before first usable", 2, &[(10, 4096)]),
        ];
        for (what, at, parts) in cases {
            let mut img = Image::new(cap, 512);
            put_gpt(&mut img, 34, lu, at, 128, parts);
            wipe(&mut img, cap - 512, 512); // the primary alone
            img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
            let arming = judge(&img);
            assert!(arming.claims.is_empty(), "{what}: {arming:?}");
            assert_eq!(arming.table, "opaque-gpt-invalid", "{what}");
        }
        // A header copy that names another LBA as its own.
        let mut img = Image::new(cap, 512);
        put_gpt(&mut img, 34, lu, 2, 128, &[]);
        let mut h = [0u8; 92];
        img.read(512, &mut h);
        h[24..32].copy_from_slice(&5u64.to_le_bytes());
        h[16..20].fill(0);
        let c = crc32(&h);
        h[16..20].copy_from_slice(&c.to_le_bytes());
        img.put(512, &h);
        wipe(&mut img, cap - 512, 512);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert!(arming.claims.is_empty());
        assert_eq!(arming.table, "opaque-gpt-invalid");
        // And the same disk, untouched, is an ordinary empty GPT: the sink
        // arms (the validation is not refusing everything).
        let mut ok = Image::new(cap, 512);
        put_gpt(&mut ok, 34, lu, 2, 128, &[]);
        ok.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&ok);
        assert_eq!(arming.table, "gpt");
        assert_eq!(arming.claims.len(), 1, "{arming:?}");
    }

    /// The independent byte oracle for the provisioned log-sink header (v3).
    #[test]
    fn provisioned_log_header_bytes() {
        let h = provisioning_log_header(SINK);
        assert_eq!(&h[..11], b"NEO_LOG_v1\0");
        assert_eq!(&h[0x10..0x18], &[0, 0, 0, 1, 0, 0, 0, 0], "16 MiB, LE");
        assert_eq!(&h[0x88..0x8c], &[3, 0, 0, 0], "header version 3");
        assert!(h[0x0b..0x10].iter().all(|&b| b == 0));
        assert!(h[0x18..0x88].iter().all(|&b| b == 0));
        assert!(h[0x8c..0xfe0].iter().all(|&b| b == 0));
        assert_eq!(h[0xfe0..], *blake3::hash(&h[..0xfe0]).as_bytes(), "seal");
        assert_eq!(log_region_bytes(&h), Some(SINK));
        // The old unsealed header (just the magic) no longer validates.
        let mut old = [0u8; LOG_HEADER_SIZE];
        old[..11].copy_from_slice(b"NEO_LOG_v1\0");
        assert_eq!(log_region_bytes(&old), None);
        // Any flipped byte breaks the seal.
        let mut bent = h;
        bent[0x40] ^= 1;
        assert_eq!(log_region_bytes(&bent), None);
    }

    /// The independent byte oracle for the scratch sector.
    #[test]
    fn scratch_sector_bytes() {
        let s = scratch_sector(64 * MIB);
        assert_eq!(&s[..32], b"NEOPLUTARCH_SCRATCH_DISK_v2\0\0\0\0\0");
        assert_eq!(&s[32..40], &[0, 0, 0, 4, 0, 0, 0, 0], "64 MiB, LE");
        assert!(s[40..480].iter().all(|&b| b == 0));
        assert_eq!(s[480..], *blake3::hash(&s[..480]).as_bytes());
        assert!(scratch_valid(&s, 64 * MIB));
        assert!(!scratch_valid(&s, 128 * MIB), "a copy on another disk");
    }

    #[test]
    fn neofs_superblock_validation() {
        let sb = neofs_superblock(1000);
        assert_eq!(neofs_volume_bytes(&sb), Some(1000 * 4096));
        let mut bare = [0u8; 512];
        bare[..8].copy_from_slice(b"NEOFSv1\0");
        assert_eq!(neofs_volume_bytes(&bare), None, "bare magic");
        let mut bent = sb;
        bent[16] ^= 1;
        assert_eq!(neofs_volume_bytes(&bent), None, "checksum");
    }

    /// The PM's case: a Windows GPT disk with the bare magics, AND with
    /// fully sealed markers, at every probe offset (a file holding them
    /// cluster-aligned): nothing arms.
    #[test]
    fn windows_gpt_disk_never_arms() {
        let cap = 954 * GIB;
        let mut img = windows_gpt(cap);
        let probes = [MIB, 64 * MIB, LOG_REGION_OFFSET];
        for &at in &probes {
            img.put(at, b"NEOFSv1\0NEO_LOG_v1\0NEO_SCRATCH_v1\0\0");
        }
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "bare magics: {arming:?}");
        assert_eq!(arming.table, "gpt");

        // Now sealed, valid-looking markers in the same places.
        img.put(MIB, &neofs_superblock(1000));
        img.put(64 * MIB, &neofs_superblock(1000));
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        img.put(cap - SCRATCH_SECTOR as u64, &scratch_sector(cap));
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "sealed markers: {arming:?}");
        assert_eq!(
            arming.blocked_by_table, 3,
            "neofs, sink and scratch blocked"
        );
        assert!(!arming.allows(0, 512), "LBA 0 never writable");
    }

    /// The same disk with a 4 KiB logical sector size.
    #[test]
    fn gpt_with_4k_sectors_still_parses() {
        let cap = 64 * GIB;
        let ss = 4096u64;
        let mut img = Image::new(cap, ss);
        let last = cap / ss - 1;
        // 128 x 128 B entries are four 4 KiB sectors: LBA 2..6.
        put_gpt(&mut img, 6, last - 5, 2, 128, &[(256, last - 5)]); // from 1 MiB
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt");
    }

    /// A protective MBR with no readable GPT: the whole disk is allocated.
    #[test]
    fn protective_mbr_without_gpt_is_opaque() {
        let cap = 2 * GIB;
        let mut img = Image::new(cap, 512);
        let mut mbr = [0u8; 512];
        mbr[446 + 4] = 0xee;
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        img.put(0, &mbr);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert_eq!(arming.table, "opaque-gpt-invalid");
        assert!(arming.claims.is_empty());
    }

    /// A sealed sink header arms ONLY its 16 MiB region: LBA 0 and the bytes
    /// on either side stay unwritable.
    #[test]
    fn sink_claim_is_scoped_to_its_region() {
        let cap = 512 * MIB;
        let mut img = Image::new(cap, 512);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert_eq!(arming.claims.len(), 1);
        assert_eq!(arming.claims[0].marker, WriteMarker::LogSink);
        assert_eq!(
            arming.claims[0].extent,
            Extent {
                start: LOG_REGION_OFFSET,
                end: LOG_REGION_OFFSET + SINK
            }
        );
        assert!(arming.allows(LOG_REGION_OFFSET, LOG_REGION_OFFSET + 4096));
        assert!(arming.allows(LOG_REGION_OFFSET + SINK - 512, LOG_REGION_OFFSET + SINK));
        assert!(!arming.allows(0, 512), "LBA 0");
        assert!(
            !arming.allows(LOG_REGION_OFFSET - 512, LOG_REGION_OFFSET + 512),
            "straddles"
        );
        assert!(!arming.allows(LOG_REGION_OFFSET + SINK, LOG_REGION_OFFSET + SINK + 512));
    }

    /// A raw-written ISO (MBR partition over its own few MiB) beside a sink
    /// region provisioned past it: the sink arms, the ISO stays unwritable.
    #[test]
    fn sink_beyond_an_iso_partition_arms() {
        let cap = 4 * GIB;
        let mut img = Image::new(cap, 512);
        let mut mbr = [0u8; 512];
        mbr[446 + 4] = 0x0c;
        mbr[446 + 8..446 + 12].copy_from_slice(&0u32.to_le_bytes());
        mbr[446 + 12..446 + 16].copy_from_slice(&(200 * 2048u32).to_le_bytes()); // 200 MiB
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        img.put(0, &mbr);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert_eq!(arming.table, "mbr");
        assert_eq!(arming.claims.len(), 1);
        assert!(!arming.allows(0, 512));
        assert!(arming.allows(LOG_REGION_OFFSET, LOG_REGION_OFFSET + 4096));
        // ...and a sink inside the partition is blocked.
        let mut inside = Image::new(cap, 512);
        let mut mbr2 = mbr;
        mbr2[446 + 12..446 + 16].copy_from_slice(&(300 * 2048u32).to_le_bytes());
        inside.put(0, &mbr2);
        inside.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&inside);
        assert!(arming.claims.is_empty());
        assert_eq!(arming.blocked_by_table, 1);
    }

    /// A NEOFS volume arms its own extent, from any valid copy.
    #[test]
    fn neofs_claims_its_volume() {
        let cap = 256 * MIB;
        let mut img = Image::new(cap, 512);
        img.put(0, &neofs_superblock(1000));
        let arming = judge(&img);
        assert_eq!(arming.claims.len(), 1);
        assert_eq!(
            arming.claims[0].extent,
            Extent {
                start: 0,
                end: 1000 * 4096
            }
        );
        assert!(arming.allows(0, 4096));
        assert!(
            !arming.allows(1000 * 4096, 1000 * 4096 + 512),
            "past the volume"
        );

        // A corrupt primary with a valid copy at 1 MiB (crash recovery).
        let mut img = Image::new(cap, 512);
        img.put(0, b"garbage");
        img.put(MIB, &neofs_superblock(1000));
        assert_eq!(judge(&img).claims.len(), 1);

        // A volume larger than the device is not believed.
        let mut img = Image::new(cap, 512);
        img.put(0, &neofs_superblock(cap / 4096 + 1));
        assert!(judge(&img).claims.is_empty());
    }

    /// A sealed scratch sector arms the whole (table-less) device, but only
    /// on the device whose capacity it names.
    #[test]
    fn scratch_claims_the_whole_device() {
        let cap = 64 * MIB;
        let mut img = Image::new(cap, 512);
        img.put(cap - 512, &scratch_sector(cap));
        let arming = judge(&img);
        assert_eq!(arming.claims.len(), 1);
        assert!(arming.allows(0, cap));

        let mut copied = Image::new(cap + MIB, 512);
        copied.put(cap + MIB - 512, &scratch_sector(cap));
        assert!(judge(&copied).claims.is_empty());

        // The old bare scratch magic no longer arms.
        let mut old = Image::new(cap, 512);
        old.put(cap - 512, b"NEO_SCRATCH_v1\0\0");
        assert!(judge(&old).claims.is_empty());
    }

    #[test]
    fn an_empty_disk_never_arms() {
        let arming = judge(&Image::new(GIB, 512));
        assert!(arming.claims.is_empty());
        assert_eq!(arming.table, "none");
    }

    // ── R1 pass 1: fail-closed partition rule (R1-1, R1-2) and NEOFS (R1-6) ──

    /// R1 P1: LBA 0 zeroed, LBA 1 unreadable. The backup is honoured; with
    /// the backup gone too, the unreadable header still protects the disk.
    #[test]
    fn r1_p1_unreadable_primary_header() {
        let cap = 954 * GIB;
        let mut img = windows_with_markers(cap, false);
        wipe(&mut img, 0, 512);
        img.bad = Some((512, 1024));
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt-backup");
        wipe(&mut img, cap - 512, 512);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-gpt-invalid");
        // And an unreadable LBA 0.
        let mut img = Image::new(8 * GIB, 512);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        img.bad = Some((0, 512));
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "opaque-unreadable");
    }

    /// R1 P2: LBA 0 and 1 zeroed, the backup header and entries intact.
    #[test]
    fn r1_p2_wiped_primary_backup_intact() {
        let cap = 954 * GIB;
        let mut img = windows_with_markers(cap, false);
        wipe(&mut img, 0, 1024);
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt-backup");
    }

    /// R1 P3: a hybrid MBR, 0xEE over LBA 1..2047 and an NTFS (0x07)
    /// partition over [200 MiB, 600 MiB), beside a valid GPT that lists
    /// only an ESP over [1 MiB, 100 MiB). The MBR-only partition covers the
    /// sink: it stays unwritten.
    #[test]
    fn r1_p3_hybrid_mbr_partition_is_kept() {
        let cap = 8 * GIB;
        let mut img = Image::new(cap, 512);
        let last = cap / 512 - 1;
        put_gpt(&mut img, 34, last - 33, 2, 128, &[(2048, 204_799)]);
        let mut mbr = [0u8; 512];
        let entry = |mbr: &mut [u8; 512], i: usize, kind: u8, start: u32, len: u32| {
            let e = 446 + 16 * i;
            mbr[e + 4] = kind;
            mbr[e + 8..e + 12].copy_from_slice(&start.to_le_bytes());
            mbr[e + 12..e + 16].copy_from_slice(&len.to_le_bytes());
        };
        entry(&mut mbr, 0, 0xee, 1, 2047);
        entry(&mut mbr, 1, 0x07, 200 * 2048, 400 * 2048);
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        img.put(0, &mbr);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&img);
        assert!(arming.claims.is_empty(), "{arming:?}");
        assert_eq!(arming.table, "gpt");
        assert_eq!(arming.blocked_by_table, 1);
    }

    /// R1 P4: a whole-disk NTFS volume (no partition table), and the other
    /// whole-disk contents we recognise: each is someone's disk.
    #[test]
    fn r1_p4_whole_disk_volumes_are_opaque() {
        let cap = 8 * GIB;
        let fresh = || {
            let mut img = Image::new(cap, 512);
            img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
            img
        };
        let boot = |prefix: &[u8], at: usize, text: &[u8], sig: bool| {
            let mut b = [0u8; 512];
            b[..prefix.len()].copy_from_slice(prefix);
            b[at..at + text.len()].copy_from_slice(text);
            if sig {
                b[510] = 0x55;
                b[511] = 0xaa;
            }
            b
        };
        let cases: [(&str, u64, Vec<u8>); 9] = [
            (
                "ntfs",
                0,
                boot(&[0xeb, 0x52, 0x90], 3, b"NTFS    ", true).to_vec(),
            ),
            (
                "exfat",
                0,
                boot(&[0xeb, 0x76, 0x90], 3, b"EXFAT   ", true).to_vec(),
            ),
            (
                "bitlocker",
                0,
                boot(&[0xeb, 0x58, 0x90], 3, b"-FVE-FS-", true).to_vec(),
            ),
            (
                "fat32",
                0,
                boot(&[0xeb, 0x58, 0x90], 82, b"FAT32   ", true).to_vec(),
            ),
            ("luks", 0, b"LUKS\xba\xbe\x00\x02".to_vec()),
            ("lvm", 512, b"LABELONE".to_vec()),
            ("ext4", 1080, vec![0x53, 0xef]),
            ("iso9660", 32768, b"\x01CD001\x01".to_vec()),
            ("boot signature, empty table", 510, vec![0x55, 0xaa]),
        ];
        for (what, at, bytes) in cases {
            let mut img = fresh();
            img.put(at, &bytes);
            let arming = judge(&img);
            assert!(arming.claims.is_empty(), "{what}: {arming:?}");
            assert!(
                arming.table.starts_with("opaque-"),
                "{what}: {}",
                arming.table
            );
        }
        // An empty disk with only a sealed sink header: ours, it arms.
        let arming = judge(&fresh());
        assert_eq!(arming.table, "none");
        assert_eq!(arming.claims.len(), 1);
    }

    /// R1-1 (d): MBR entries are sanity-checked: a bad boot flag or an
    /// entry past the device makes the table opaque, not a list of garbage.
    #[test]
    fn r1_malformed_mbr_is_opaque() {
        let cap = 8 * GIB;
        let total = (cap / 512) as u32;
        for (what, status, start, len) in [
            ("boot flag 0x13", 0x13u8, 2048u32, 1000u32),
            ("past the device", 0x00, 2048, total),
            ("zero length", 0x80, 2048, 0),
        ] {
            let mut img = Image::new(cap, 512);
            let mut mbr = [0u8; 512];
            mbr[446] = status;
            mbr[446 + 4] = 0x0c;
            mbr[446 + 8..446 + 12].copy_from_slice(&start.to_le_bytes());
            mbr[446 + 12..446 + 16].copy_from_slice(&len.to_le_bytes());
            mbr[510] = 0x55;
            mbr[511] = 0xaa;
            img.put(0, &mbr);
            img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
            let arming = judge(&img);
            assert!(arming.claims.is_empty(), "{what}: {arming:?}");
            assert_eq!(arming.table, "opaque-mbr-invalid", "{what}");
        }
    }

    /// R1 P5: a valid 65 MiB primary NEOFS volume whose 64 MiB copy is stale
    /// and says 1 GiB: only the primary's volume is armed. With no valid
    /// primary, copies must agree.
    #[test]
    fn r1_p5_neofs_primary_alone_sets_the_extent() {
        let cap = 2 * GIB;
        let blocks = 65 * MIB / 4096;
        let mut img = Image::new(cap, 512);
        img.put(0, &neofs_superblock(blocks));
        img.put(64 * MIB, &neofs_superblock(GIB / 4096));
        let arming = judge(&img);
        assert_eq!(arming.claims.len(), 1, "{arming:?}");
        assert_eq!(
            arming.claims[0].extent,
            Extent {
                start: 0,
                end: 65 * MIB
            }
        );
        assert!(!arming.allows(LOG_REGION_OFFSET, LOG_REGION_OFFSET + 4096));
        // No primary: two copies that disagree arm nothing...
        let mut img = Image::new(cap, 512);
        img.put(MIB, &neofs_superblock(blocks));
        img.put(64 * MIB, &neofs_superblock(GIB / 4096));
        assert!(judge(&img).claims.is_empty());
        // ...two that agree arm their volume.
        let mut img = Image::new(cap, 512);
        img.put(MIB, &neofs_superblock(GIB / 4096));
        img.put(64 * MIB, &neofs_superblock(GIB / 4096));
        let arming = judge(&img);
        assert_eq!(arming.claims.len(), 1, "{arming:?}");
        assert_eq!(arming.claims[0].extent.end, GIB);
    }

    // ── R1 pass 2 follow-up: R1-7 (blank-start allow-list) ──

    /// R1-7: on a disk with no partition table, a sink arms only if the
    /// first MiB is blank; data there that matches no signature we know
    /// still blocks it.
    #[test]
    fn r1_7_sink_needs_a_blank_start_on_a_table_less_disk() {
        let cap = 8 * GIB;
        let mut blank = Image::new(cap, 512);
        blank.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&blank);
        assert_eq!(arming.table, "none");
        assert_eq!(arming.claims.len(), 1, "{arming:?}");
        // Unknown data anywhere in the first MiB: someone's disk.
        for at in [0u64, 4096, 100 * 1024, MIB - 1] {
            let mut used = Image::new(cap, 512);
            used.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
            used.put(at, &[0x5a]);
            let arming = judge(&used);
            assert!(arming.claims.is_empty(), "at {at}: {arming:?}");
            assert_eq!(arming.table, "none-start-in-use", "at {at}");
            assert_eq!(arming.blocked_by_table, 1);
        }
        // Data just past the first MiB does not count.
        let mut past = Image::new(cap, 512);
        past.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        past.put(MIB, &[0x5a]);
        assert_eq!(judge(&past).claims.len(), 1);
        // A read error in the first MiB is not blank.
        let mut bad = Image::new(cap, 512);
        bad.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        bad.bad = Some((64 * 1024, 64 * 1024 + 512));
        assert!(judge(&bad).claims.is_empty());
        // Our own NEOFS primary at LBA 0 is exempt: its volume and a sink
        // past it both arm.
        let mut ours = Image::new(cap, 512);
        ours.put(0, &neofs_superblock(64 * MIB / 4096));
        ours.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let arming = judge(&ours);
        assert_eq!(arming.claims.len(), 2, "{arming:?}");
        // A scratch disk is not a sink: its claim does not need the rule.
        let mut scratch = Image::new(64 * MIB, 512);
        scratch.put(4096, &[0x5a]);
        scratch.put(64 * MIB - SCRATCH_SECTOR as u64, &scratch_sector(64 * MIB));
        assert_eq!(judge(&scratch).claims.len(), 1);
    }

    /// R1-7 second layer: the added whole-disk signatures are each opaque
    /// (every claim dropped, a scratch claim included).
    #[test]
    fn r1_7_more_whole_disk_signatures() {
        let cap = 8 * GIB;
        let cases: [(&str, u64, &[u8]); 12] = [
            ("xfs", 0, b"XFSB"),
            ("apfs", 32, b"NXSB"),
            ("refs", 3, b"ReFS"),
            ("hfs+", 1024, b"H+"),
            ("hfsx", 1024, b"HX"),
            ("f2fs", 1024, &[0x10, 0x20, 0xf5, 0xf2]),
            ("btrfs", 0x1_0040, b"_BHRfS_M"),
            ("md 1.1", 0, &[0xfc, 0x4e, 0x2b, 0xa9]),
            ("md 1.2", 4096, &[0xfc, 0x4e, 0x2b, 0xa9]),
            ("zfs", 0x2_0000, &[0x0c, 0xb1, 0xba, 0x00]),
            ("swap", 4086, b"SWAPSPACE2"),
            ("swap (old)", 4086, b"SWAP-SPACE"),
        ];
        for (what, at, magic) in cases {
            let mut img = Image::new(cap, 512);
            img.put(at, magic);
            img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
            img.put(cap - SCRATCH_SECTOR as u64, &scratch_sector(cap));
            let arming = judge(&img);
            assert!(arming.claims.is_empty(), "{what}: {arming:?}");
            assert_eq!(arming.table, "opaque-filesystem", "{what}");
        }
    }

    // === OT-87 R3: the differential KAT ===
    //
    // The guard's GPT parser moved into `gpt_logic.rs` (one parser for the
    // guard, the partition view and xtask). The new guard must judge every
    // disk exactly as main's did (`legacy_write_guard_logic`, frozen at
    // e0a59501): the same claims, extents, blocked count and table name, over
    // the guard corpus and a byte-mutation sweep of each table.

    use super::legacy_write_guard_logic as legacy;

    impl legacy::Disk for Image {
        fn capacity(&self) -> u64 {
            self.capacity
        }

        fn sector_size(&self) -> u64 {
            self.sector
        }

        fn read(&self, offset: u64, out: &mut [u8]) -> bool {
            Disk::read(self, offset, out)
        }
    }

    /// The two guards' judgements, and their tables, compared as text (they
    /// are different types with the same shape).
    fn same_judgement(img: &Image, what: &str) {
        let new = format!("{:?}", judge(img));
        let old = format!("{:?}", legacy::judge(img));
        assert_eq!(new, old, "{what}: judge");
        let new = format!("{:?}", super::write_guard_logic::read_table(img));
        let old = format!("{:?}", legacy::read_table(img));
        assert_eq!(new, old, "{what}: read_table");
    }

    /// The §4.4 oracle disk (S = 512 or 4096), its table only.
    fn oracle_disk(s: u64) -> Image {
        use super::gpt_oracle::{DISK_GUID, ESP_GUID, NEOFS_GUID};
        let l = super::gpt_logic::gpt_layout(
            s,
            4 * GIB / s - 1,
            DISK_GUID,
            ESP_GUID,
            NEOFS_GUID,
            false,
        )
        .unwrap();
        let mut img = Image::new(4 * GIB, s);
        img.put(0, &l.mbr);
        img.put(s, &l.primary_header);
        img.put(2 * s, &l.entries);
        img.put(l.backup_entries_lba * s, &l.entries);
        img.put(l.last_lba * s, &l.backup_header);
        img
    }

    /// A 2 GiB disk whose two header copies both validate but disagree: the
    /// primary lists one partition, the backup another.
    fn disagreeing_copies() -> Image {
        let cap = 2 * GIB;
        let mut img = Image::new(cap, 512);
        let last = cap / 512 - 1;
        put_gpt(&mut img, 34, last - 33, 2, 128, &[(2048, 4095)]);
        // A second, sealed table over the backup copy only.
        let mut other = Image::new(cap, 512);
        put_gpt(&mut other, 34, last - 33, 2, 128, &[(8192, last - 33)]);
        for at in [(last - 32) * 512, last * 512] {
            let len = if at == last * 512 { 512 } else { 32 * 512 };
            let mut buf = vec![0u8; len];
            Disk::read(&other, at, &mut buf);
            img.put(at, &buf);
        }
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        img
    }

    fn corpus() -> Vec<(&'static str, Image)> {
        let cap = 954 * GIB;
        let mut v: Vec<(&'static str, Image)> = vec![
            ("windows", windows_gpt(cap)),
            ("windows+markers", windows_with_markers(cap, false)),
            ("windows primary only", windows_primary_only(cap)),
            ("oracle 512", oracle_disk(512)),
            ("oracle 4096", oracle_disk(4096)),
            ("disagreeing copies", disagreeing_copies()),
        ];
        // The disagreeing disk with its primary gone: the backup's table.
        let mut d = disagreeing_copies();
        wipe(&mut d, 512, 512);
        v.push(("disagreeing, primary wiped", d));
        // A protective MBR and no GPT at all.
        let mut p = Image::new(2 * GIB, 512);
        let mut mbr = [0u8; 512];
        mbr[446 + 4] = 0xee;
        mbr[510] = 0x55;
        mbr[511] = 0xaa;
        p.put(0, &mbr);
        p.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        v.push(("protective MBR only", p));
        // 4 KiB sectors.
        let mut k = Image::new(64 * GIB, 4096);
        let last = 64 * GIB / 4096 - 1;
        put_gpt(&mut k, 6, last - 5, 2, 128, &[(256, last - 5)]);
        k.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        v.push(("4k gpt", k));
        // An unreadable primary header (a bad sector).
        let mut u = windows_with_markers(cap, false);
        u.bad = Some((512, 1024));
        v.push(("unreadable primary", u));
        // A whole-disk NeoFS volume, and an empty disk.
        let mut n = Image::new(GIB, 512);
        n.put(0, &neofs_superblock(1000));
        v.push(("whole-disk neofs", n));
        v.push(("empty", Image::new(GIB, 512)));
        v
    }

    #[test]
    fn differential_corpus() {
        for (what, img) in corpus() {
            same_judgement(&img, what);
        }
    }

    /// A sealed table whose two entries overlap, with the log-sink header in
    /// free space past them.
    fn overlapping_entries(parts: &[(u64, u64)]) -> Image {
        let cap = 2 * GIB;
        let mut img = Image::new(cap, 512);
        put_gpt(&mut img, 34, cap / 512 - 34, 2, 128, parts);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        img
    }

    /// The one named divergence from the frozen legacy guard (Muse, R3
    /// review item 5). Overlapping entries: the legacy parser believes the
    /// table and arms the sink in free space; the new one refuses the table
    /// (`opaque-gpt-invalid`) and arms nothing. Only write permission is
    /// removed. Touching entries are still judged identically.
    #[test]
    fn differential_expected_divergence_overlapping_entries() {
        for parts in [
            [(2048u64, 4095u64), (4000, 8191)],
            [(2048, 4096), (4096, 8191)],
            [(2048, 8191), (2048, 8191)],
        ] {
            let img = overlapping_entries(&parts);
            let old = legacy::judge(&img);
            assert_eq!(old.table, "gpt", "{parts:?}");
            assert_eq!(old.claims.len(), 1, "legacy arms the sink: {old:?}");
            let new = judge(&img);
            assert_eq!(new.table, "opaque-gpt-invalid", "{parts:?}");
            assert!(new.claims.is_empty(), "{new:?}");
            assert!(new.blocked_by_table >= old.blocked_by_table);
        }
        let touching = overlapping_entries(&[(2048, 4095), (4096, 8191)]);
        same_judgement(&touching, "touching entries");
        assert_eq!(judge(&touching).claims.len(), 1);
    }

    /// The second named divergence (Janus, R3 review item 7): a primary
    /// whose usable range reaches the backup array (`last_usable` = the last
    /// LBA, alternate there too), one small partition, the log sink in free
    /// space. The legacy parser believes it and arms the sink; the new one
    /// refuses the copy (`opaque-gpt-invalid`). Only write permission is
    /// removed.
    #[test]
    fn differential_expected_divergence_usable_range_over_the_backup() {
        let cap = 2 * GIB;
        let last = cap / 512 - 1;
        let mut img = Image::new(cap, 512);
        put_gpt(&mut img, 34, last, 2, 128, &[(2048, 4095)]);
        // put_gpt put the backup array past last_usable, which is now the
        // device's end: wipe the backup header, as Janus's case has only a
        // primary.
        img.put(last * 512, &[0u8; 512]);
        img.put(LOG_REGION_OFFSET, &provisioning_log_header(SINK));
        let old = legacy::judge(&img);
        assert_eq!(old.table, "gpt");
        assert_eq!(old.claims.len(), 1, "legacy arms the sink: {old:?}");
        let new = judge(&img);
        assert_eq!(new.table, "opaque-gpt-invalid");
        assert!(new.claims.is_empty(), "{new:?}");
    }

    /// Every byte of each header copy and of the first entries, flipped one
    /// at a time: the two guards agree on each mutant (most are refused, a
    /// few change only a partition's extent).
    #[test]
    fn differential_mutation_sweep() {
        let cap = 954 * GIB;
        let bases: Vec<(&'static str, Image)> = vec![
            ("windows", windows_with_markers(cap, false)),
            ("windows primary only", windows_primary_only(cap)),
            ("oracle 512", oracle_disk(512)),
            ("oracle 4096", oracle_disk(4096)),
            ("disagreeing copies", disagreeing_copies()),
        ];
        let mut mutants = 0;
        for (what, mut base) in bases {
            let s = base.sector;
            let last = base.capacity / s - 1;
            // The primary header, the first two primary entries, the backup
            // header.
            let mut offsets: Vec<u64> = (s..s + 92).collect();
            let entries_lba = {
                let mut b = [0u8; 8];
                Disk::read(&base, s + 72, &mut b);
                u64::from_le_bytes(b)
            };
            offsets.extend(entries_lba * s..entries_lba * s + 256);
            offsets.extend(last * s..last * s + 92);
            for at in offsets {
                let mut b = [0u8; 1];
                Disk::read(&base, at, &mut b);
                base.put(at, &[b[0] ^ 0x01]);
                same_judgement(&base, &format!("{what} @{at:#x}"));
                base.put(at, &b);
                mutants += 1;
            }
        }
        assert!(mutants > 2000, "{mutants}");
    }
}
